import { useSubmit } from "@kasperrt/smolter/preact";

export function SearchShortcut() {
  const submit = useSubmit();

  return (
    <button onClick={() => void submit({ q: "routing" }, {
      action: "/search",
      method: "GET",
      replace: true,
    })}>
      Search routing
    </button>
  );
}
